    m=checked(decode_military_seed(tick6));i=checked(decode_interaction_seed(tick6));t=checked(decode_travel_seed(tick6));c=CommonStore(domain_common(tick6,*common),common);c.bind_membership(&services.membership);assert(army_at_settlement(c,m,tc,"army:2925","village.east"));auto contacts=checked(probe_military_contacts(c,m,mc,t,tc,services));assert(contacts.ordered_hits.empty());require(check_military_contact_capability(c,m,mc,t,tc,services));auto stored=checked(export_military_state(m));auto checkpoint_before=encode_common_state(c.state());auto model=mc;model.march_condition_model=true;auto blocked=check_military_contact_capability(c,m,model,t,tc,services);assert(!blocked.ok&&blocked.error.kind==ErrorKind::unsupported_capability&&blocked.error.command=="military_march");equal(stored,checked(export_military_state(m)),"march unsupported unchanged military");equal(checkpoint_before,encode_common_state(c.state()),"march unsupported unchanged common");
